        <audio
          ref="audioRef"
          :src="audioSrc"
          loop
          controls
          @timeupdate="onTimeUpdate"
          class="audio"
        ></audio>
        <div class="poemBox" ref="poemBoxRef">
          <ul
            class="poemList"
            ref="poemListRef"
            :style="{ transform: `translateY(${-offset}px)` }"
          >
            <li
              :ref="(el) => setLiRefs(el, index)"
              v-for="(line, index) in lyrics"
              :key="index"
              :class="{ active: index === currentIndex }"
            >
