<script setup>
import { ref, reactive, onMounted, onUnmounted, nextTick } from "vue";
import timer from "@/components/timerCom/timerCom.vue";
import { geci } from "@/assets/lsc/data.js";
import router from "@/router";
import { getHomePoems } from "@/utils/CloudStore.js";

const hearts = ref([]);
const state = reactive({
  poemList: [],
});

// 创建爱心动画函数
function createHearts() {
  for (let i = 0; i < 2; i++) {
    const heart = {
      id: Date.now() + i,
      style: {
        left: `${Math.random() * 100}%`,
        animationDuration: `${Math.random() * 2 + 2}s`,
      },
    };
    hearts.value.push(heart);
    //5秒s后清除爱心
    setTimeout(() => {
      hearts.value = hearts.value.filter((h) => h.id !== heart.id);
    }, 5000);
  }
}

//接口诗句处理
const cutPoem = (poemStr) => {
  //判断数据是否为空
  if (typeof poemStr !== "string" || poemStr.trim() === "") return null;
  // 先统一替换英文逗号为中文逗号，或者直接用英文逗号分割
  const poem = poemStr.replace(/,/g, "，");
  const FirstTitle = poem.split("，");
  return {
    title: FirstTitle[0],
    lines: FirstTitle.slice(1)
      .map((line) => line.trim())
      .filter((line) => line.length > 0),
  };
};

const currentPoem = ref(null);

function getRandomIndex(excludeIndex) {
  let idx;
  do {
    idx = Math.floor(Math.random() * state.poemList.length);
  } while (idx === excludeIndex && state.poemList.length > 1);
  return idx;
}

//歌词的展示
const rawLyrics = geci;
const audioRef = ref(null);
const audioSrc =
  "https://raw.githubusercontent.com/404WTF-J/TestLink/9cc8a4f85063c6f00317737986c0b390c4c2e8a1/Luckyfile/asseset/video/Special%20someone.mp3";
const poemBoxRef = ref(null);
const poemListRef = ref(null);
const liRefs = ref([]); // 存储每个li元素的引用
// console.log(rawLyrics, "rawLyrics138");

// 解析歌词文本，返回数组 [{times: 秒数, text: 歌词}]
function parseLyrics(rawLyrics) {
  const lines = rawLyrics.split("\n");
  const result = [];
  for (const line of lines) {
    const parts = line.split("]");
    if (parts.length < 2) continue;
    const timeStr = parts[0].substring(1);
    const text = parts[1].trim();
    const times = parseTime(timeStr);
    result.push({ times, text });
  }
  return result;
}

// 时间字符串转秒数，支持 mm:ss.xx 格式
function parseTime(timeStr) {
  const [min, sec] = timeStr.split(":");
  return parseInt(min) * 60 + parseFloat(sec);
}

const lyrics = reactive(parseLyrics(rawLyrics));
const currentIndex = ref(0);
const offset = ref(0);

function onTimeUpdate() {
  if (!audioRef.value) return;
  const currentTime = audioRef.value.currentTime;

  // 找到当前歌词索引
  let i = 0;
  for (; i < lyrics.length; i++) {
    if (currentTime < lyrics[i].times) {
      i = i - 1;
      break;
    }
  }
  if (i < 0) i = 0;
  if (i >= lyrics.length) i = lyrics.length - 1;
  currentIndex.value = i;

  // 计算滚动偏移
  nextTick(() => {
    if (!poemBoxRef.value || !poemListRef.value) return;
    const poemBoxHeight = poemBoxRef.value.clientHeight;
    const liHeight = liRefs.value[0]?.clientHeight || 0;
    const maxOffset = poemListRef.value.scrollHeight - poemBoxHeight;
    // console.log(
    //   liHeight,
    //   "liHeight",
    //   poemBoxHeight,
    //   "poemBoxHeight",
    //   maxOffset,
    //   "maxOffset",
    //   "879"
    // );
    let newOffset = liHeight * i - poemBoxHeight / 2 + liHeight / 2;
    if (newOffset < 0) newOffset = 0;
    if (newOffset > maxOffset) newOffset = maxOffset;

    offset.value = newOffset;
  });
}

// 用于收集li元素的引用
function setLiRefs(el) {
  if (el) liRefs.value.push(el);
}

//跳转到歌曲页
const gosinerPage = () => {
  audioRef.value.pause();
  router.push("/Spmusic");
};

//跳转到留言板页
const gomessagePage = () => {
  audioRef.value.pause();
  router.push("/MessageBoard");
};

// 跳转到pic页
const gopicareaPage = () => {
  audioRef.value.pause();
  router.push("/Picarea");
};

// 跳转到letter页
const goletterPage = () => {
  router.push("/Letter");
};

// 跳转到todo页
const gotodoPage = () => {
  router.push("/Togethertodo");
};

onMounted(async () => {
  // 持续调用创建爱心函数
  setInterval(createHearts, 300);

  // 获取诗句
  const res = await getHomePoems();
  state.poemList = res
    .filter(
      (item) =>
        typeof item.PoemContent === "string" && item.PoemContent.trim() !== ""
    )
    .map((item) => cutPoem(item.PoemContent));
  // console.log(state.poemList, "处理后的诗句287");

  // 随机选一首诗
  // 随机选一个索引
  // 读取上次显示的索引
  const lastIndex = sessionStorage.getItem("lastPoemIndex");
  const lastIdxNum = lastIndex !== null ? parseInt(lastIndex) : -1;

  // 随机选一个不等于上次的索引
  const newIndex = getRandomIndex(lastIdxNum);

  // 设置当前诗歌
  currentPoem.value = state.poemList[newIndex];

  // 记录当前索引到 sessionStorage
  sessionStorage.setItem("lastPoemIndex", newIndex);

  // 组件挂载后清空liRefs，防止重复
  liRefs.value = [];
});
onUnmounted(() => {
  // 生命周期钩子
  clearInterval(createHearts);
});
</script>

